local function add_slot_control(key,maximum)
   local controls=gui.elements.affix_settings
   controls[key.."_slider"]=controls[key.."_slider"]
      or slider_int:new(-1,maximum,-1,get_hash(plugin_label.."_"..key.."_slider"))
end
for _,slot in ipairs({"1h_scythe","2h_scythe","flail","shield"}) do
   add_slot_control("legendary_"..slot,3)
   add_slot_control("unique_"..slot,4)
end
