local menu_stack,menu_error={},nil
local function push_tree(node,label)
   if not node:push(label) then return false end
   menu_stack[#menu_stack+1]=node
   return true
end
local function pop_tree(node)
   node:pop()
   menu_stack[#menu_stack]=nil
end
